def select_rows(rows, team):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list")
    if not isinstance(team, str) or not team.strip():
        raise ValueError("team must be a nonblank string")

    counts = {}
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("each row must be a dictionary")
        if row.get("team") != team:
            continue

        label = row.get("label")
        count = row.get("count")
        if not isinstance(label, str) or not label.strip():
            raise ValueError("selected labels must be nonblank strings")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0:
            raise ValueError("selected counts must be nonnegative integers")
        counts[label] = counts.get(label, 0) + count

    return [{"label": label, "count": counts[label]} for label in sorted(counts)]
